mapper.select:
SELECT id, name, slug, identity_version AS identityVersion, created_at, updated_at
FROM organization
WHERE id = #{id}

mapper.insert:
INSERT INTO organization_duplicate_decision_lock (organization_id)
VALUES (#{id})
ON DUPLICATE KEY UPDATE organization_id = #{id}

mapper.update:
UPDATE organization
SET

  export_data_owner = #{enabled}
  export_data_admin = #{enabled}
  id = id

WHERE id = #{id} AND lifecycle_state = 'active'
